    },
    {
      "section": "5.4.1.1",
      "label": "[REQ-1-OAD-9200]",
      "text": "The CSW shall include the set of software communication and integration services listed in 'Table: TMT Common Software services definitions' below with a general description of their functionality",
      "id": "REQ-1-OAD-9200"
    },
    {
      "section": "5.4.1.1",
      "label": "[REQ-1-OAD-9312]",
