    },
    {
      "section": "5.4.1.1",
      "label": "�",
      "text": "All OESA software subsystems or components shall have the ability to receive and parse TMT defined data structures containing command, control and configuration instructions using the Common Software Command Service.",
      "id": null
    },
    {
      "section": "5.4.1.1",
      "label": "�",
      "text": "All OESA software subsystems or components shall have the capability of transmitting and receiving TMT-defined data structures containing health, status, alarms and events using the Common Software Event Services.",
      "id": null
    },
    {
      "section": "5.4.1.1",
      "label": "�",
      "text": "Each OESA software subsystem or component shall perform a health evaluation and transmit health information (i.e., a heartbeat) at least once per second.",
      "id": null
    },
    {
      "section": "5.4.1.1",
      "label": "�",
      "text": "For the purposes of later diagnosis and analysis, each OESA software subsystem or component shall have the ability to transmit time-stamped logging information using the Common Software Logging Service.",
      "id": null
    },
    {
      "section": "5.4.1.1",
      "label": "�",
      "text": "For the purposes of process control and synchronization, each software subsystem shall be able to transmit or receive events.",
      "id": null
    },
    {
      "section": "5.4.1.1",
      "label": "�",
      "text": "For the purposes of fault detection, each OESA software subsystem or component shall have the ability to transmit an alarm using the Common Software Event Services when a situation occurs that prevents normal operations or abnormal condition occurs.",
      "id": null
    },
    {
      "section": "5.4.1.1",
      "label": "[REQ-1-OAD-9213]",
      "text": "Each CSW service shall have an Application Programming Interface (API).",
