    },
    {
      "section": "5.4.1.1",
      "label": null,
      "text": "It is a goal to make each API service implementation neutral, i.e. it shall be possible to change how a service is implemented without needing to make extensive code modifications to subsystems using that service.",
      "id": null
    },
    {
      "section": "5.4.1.2",
      "label": "[REQ-1-OAD-9223]",
      "text": "The Single Sign-on (SSO) Service shall enable OESA users to authenticate once and gain access to authorized operations.",
      "id": "REQ-1-OAD-9223"
    },
    {
      "section": "5.4.1.2",
      "label": null,
      "text": "For each user, one or more authorization roles shall be maintained.",
      "id": null
    },
    {
      "section": "5.4.1.2",
      "label": "[REQ-1-OAD-9226]",
      "text": "The Connection and Command Service shall enable one software component to create a connection to another in order to perform command and control of a specific set of OESA subsystems for specific operations.",
